/// <summary>
///    The <c>METItemPackChangeBusinessEvent</c> class extends <c>BusinessEventsBase</c> to provide item status change business event.
/// </summary>
[BusinessEvents(classStr(METItemPackChangeBusinessEventContract),
    "@MET:ItemPackChangeBusinessEventName",
    "@MET:ItemPackChangeBusinessEventDesc",
    ModuleAxapta::Inventory)]
public final class METItemPackChangeBusinessEvent extends BusinessEventsBase
{
    private METInventItemOrderSetup metInventItemOrderSetup;
       
}

Method.Source:
    /// <summary>
    /// Constructs a new METItemPackChangeBusinessEvent business event.
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">The <c>METInventItemOrderSetup</c> record.</param>
    /// <returns>A new <c>METItemPackChangeBusinessEvent</c> business event.</returns>
    public static METItemPackChangeBusinessEvent newFromMETInventItemOrderSetup(METInventItemOrderSetup _metInventItemOrderSetup)
    {
        METItemPackChangeBusinessEvent event = new METItemPackChangeBusinessEvent();
        event.parmMETInventItemOrderSetup(_metInventItemOrderSetup);

        return event;
    }

    /// <summary>
    /// parm method to set/get <t>METInventItemOrderSetup</t> buffer.
    /// </summary>
    /// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup buffer></param>
    /// <returns><t>METInventItemOrderSetup</t> buffer</returns>
    private METInventItemOrderSetup parmMETInventItemOrderSetup(METInventItemOrderSetup _metInventItemOrderSetup = metInventItemOrderSetup)
    {
        metInventItemOrderSetup = _metInventItemOrderSetup;

        return metInventItemOrderSetup;
    }

/// <summary>
/// Overrides to provide item status change data.
/// </summary>
/// <returns>The <c>METItemPackChangeBusinessEventContract</c> of the event.</returns>
public BusinessEventsContract buildContract()
{
    return METItemPackChangeBusinessEventContract::newFromMETInventItemOrderSetup(metInventItemOrderSetup);
}
